<div class="grid gap-5 sm:grid-cols-2"><label class="grid gap-2 text-sm font-bold">Plan name<input class="min-h-12 rounded-xl border border-zinc-300 px-4 font-normal" name="name" value="{{ old('name', $plan?->name) }}" required><x-input-error :messages="$errors->get('name')" /></label><label class="grid gap-2 text-sm font-bold">Duration in days<input class="min-h-12 rounded-xl border border-zinc-300 px-4 font-normal" type="number" min="1" max="1095" name="duration_days" value="{{ old('duration_days', $plan?->duration_days) }}" required><x-input-error :messages="$errors->get('duration_days')" /></label><label class="grid gap-2 text-sm font-bold">Price (PHP)<input class="min-h-12 rounded-xl border border-zinc-300 px-4 font-normal" type="number" min="0" step="0.01" name="price" value="{{ old('price', $plan?->price) }}" required><x-input-error :messages="$errors->get('price')" /></label><label class="flex min-h-12 items-center gap-3 rounded-xl bg-zinc-100 p-4 text-sm font-bold"><input type="hidden" name="is_active" value="0"><input class="size-5 accent-lime-500" type="checkbox" name="is_active" value="1" @checked(old('is_active', $plan?->is_active ?? true))> Available for enrollment</label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Description<textarea class="min-h-24 rounded-xl border border-zinc-300 p-4 font-normal" name="description">{{ old('description', $plan?->description) }}</textarea></label></div><div class="mt-7 flex justify-end gap-3"><a href="{{ route('admin.plans.index') }}" class="inline-flex min-h-12 items-center px-5 font-bold text-zinc-600">Cancel</a><button class="min-h-12 rounded-xl bg-lime-400 px-6 font-extrabold">Save plan</button></div>
